class Translator:
    def __init__(self, language="en"):
        if language not in LANGUAGES:
            raise ValueError("Unsupported interface language.")
        self.language = language
        self.index = tuple(LANGUAGES).index(language)

    def __call__(self, key, **values):
        return TEXT[key][self.index].format(**values)

    def message(self, message):
        """Translate domain output at display time, retaining unexpected diagnostics."""
        if self.language == "en":
            return message
        if message in SOURCE_MESSAGES:
            return self(SOURCE_MESSAGES[message])
        for pattern, key in MESSAGE_PATTERNS:
            match = re.fullmatch(pattern, message)
            if match:
                values = match.groupdict()
                if "metric" in values:
                    values["metric"] = self(METRIC_KEYS[values["metric"]])
                if values.get("unit") == "minutes":
                    values["unit"] = self("minutes")
                return self(key, **values)
        prefix = "A local record failed validation; the file was not changed: "
        if message.startswith(prefix):
            return self("invalid_local_record") + " " + self.message(message[len(prefix):])
        # Multiple validation errors can be joined by the storage layer.
        parts = re.split(r"(?<=\.) (?=[A-Z])", message)
        if len(parts) > 1:
            return " ".join(self.message(part) for part in parts)
        return self("technical_detail", detail=message)


METRIC_KEYS = {"Sleep": "sleep_short", "Resting heart rate": "heart", "Activity": "activity_short",
               "sleep_minutes": "sleep", "resting_hr_bpm": "heart", "activity_minutes": "activity"}
SOURCE_MESSAGES = {}
MESSAGE_PATTERNS = []


def _message(key, english, turkish, french, german, spanish):
    TEXT[key] = (english, turkish, french, german, spanish)
    SOURCE_MESSAGES[english] = key


def _pattern(key, pattern, english, turkish, french, german, spanish):
    TEXT[key] = (english, turkish, french, german, spanish)
    MESSAGE_PATTERNS.append((pattern, key))


